    return int(n) + 1

def round_half_to_even(n):
    """
    Round the given number to the half towards even

    :param n: The number to round
    :type n: int or float
    :return: The rounded number
    :rtype: int
    """
    if isinstance(n, int):
        return n

    # Check if the number is already an integer
    if n % 1 == 0:
        return int(n)

    # Extract the mantissa and exponent
    m, e = math.frexp(n)

    # Convert to an integer and back to a float
    i = math.ldexp(int(m * 2 ** 53), int(e - 53))

    # Check if the integer value is even
    if i % 2 == 0:
        return int(i / 2)
    else:
        return int(i / 2 + 1)

