def validate(path):
    # Check if path exists and is not a directory
    if not os.path.exists(path) or os.path.isdir(path):
        return False

    # Open the OCFL object via pyfs
    try:
        ocflobj = pyfs.open(path)
    except Exception:
        # If there is an exception, the path is probably not a valid OCFL object
        # so we return False
        return False

    # Check if the OCFL object has a valid header
    if not ocflobj.has_section("OCFL_HEADER"):
        return False

    # Check if the header has a valid version
    header = ocflobj.get_section("OCFL_HEADER")
    if not header.get("objectRoot").startswith("http://www.ocfl.io/1.0/"):
        return False

    # Check if the OCFL object has a valid manifest
    manifest = ocflobj.get_section("OCFL_MANIFEST")
    if not manifest.get("OCFL_VERSION", "1.0").startswith("http://www.ocfl.io/1.0/"):
        return False

