    if isinstance(commands, str):
        commands = [commands]
    if not isinstance(commands, list):
        raise ValueError("commands must be a string or a list of strings")
    if not isinstance(args, list):
        raise ValueError("args must be a list of strings")
    if verbose:
        print("Commands:", commands)
        print("Args:", args)
        print("CWD:", cwd)
    proc = subprocess.Popen(commands + args, cwd=cwd, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL if hide_stderr else subprocess.STDOUT, env=env)
    stdout, _ = proc.communicate()
    if proc.returncode != 0:
        raise subprocess.CalledProcessError(cmd=commands, returncode=proc.returncode, output=stdout)
    return stdout.decode("utf-8").strip()

