def parse_arguments(unparsed_arguments):
    global_namespace = dict()
    subparser_names = get_subparser_names()
    for unparsed_arg in unparsed_arguments:
        if unparsed_arg.startswith("--"):
            # Split argument name and value
            arg_name, arg_value = unparsed_arg.split(" ")
            arg_name = arg_name.strip("--")
            # Check if this is a global argument
            if arg_name in global_namespace:
                # Overwrite old value
                global_namespace[arg_name] = arg_value
            else:
                # Check if this is a subparser argument
                for subparser_name in subparser_names:
                    if arg_name.startswith(subparser_name):
                        # Extract subparser name
                        subparser_name = arg_name.split("--")[0]
                        # Create a new namespace if necessary
                        if subparser_name not in global_namespace:
                            global_namespace[subparser_name] = dict()
                        # Add value to the namespace
                        global_namespace[subparser_name][arg_name] = arg_value
                        break
                else:
                    # TODO: Remove this exception handling once you have validated optionally 
                    # subparser arguments in the subparser_names list
                    raise ValueError(f"Unknown command-line argument {arg_name}")
    return global_namespace

def parse_arguments(* unparsed_arguments) -> Dict[str, argparse.Namespace]:
    local_ns = {}
    for action in unparsed_arguments:
        if action.startswith("--"):
            if "=" in action:
                (key, value) = action.split("=")
                local_ns[key] = value
            else:
                local_ns[action] = None
    local_ns = argparse.Namespace(**local_ns)
    return global_ns, { "global": local_ns }

