def size_to_bytes(size: str) -> int:
    '''Convert human readable file size to bytes.

    Argument:
        size (str): A string representing a human readable file size (eg: '500K')

    Return:
        A decimal representation of file size
    '''

    suffixes = ['k', 'm', 'g', 't', 'p', 'e']
    num_and_suffix = size.lower().split('k')

    try:
        number = int(num_and_suffix[0])
        suffix = num_and_suffix[1]
    except ValueError:
        raise ValueError("Invalid input")

    try:
        suffix_idx = suffixes.index(suffix)
    except ValueError:
        raise ValueError("Unsupported suffix")

    power = suffix_idx + 1
    return number * (1000 ** power)

def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size
    """

    if not size.isdigit():
        size = size.upper()
        size = size.replace("B", "")
        if size.endswith("K"):
            return int(float(size[:-1]) * 1000)
        elif size.endswith("M"):
            return int(float(size[:-1]) * 1000**2)
        elif size.endswith("G"):
            return int(float(size[:-1]) * 1000**3)
        elif size.endswith("T"):
            return int(float(size[:-1]) * 1000**4)
        else:
            raise ValueError(f"Invalid size: {size}")
    else:
        return int(size)

