def find_roots(graph, prop, roots=None):
    """
    Find the roots in some sort of transitive hierarchy.

    find_roots(graph, rdflib.RDFS.subClassOf)
    will return a set of all roots of the sub-class hierarchy

    Assumes triple of the form (child, prop, parent), i.e. the direction of
    RDFS.subClassOf or SKOS.broader
    """
    if roots is None:
        roots = set()

    for triple in graph:
        child, _, parent = triple
        if child == parent:
            roots.add(child)
        else:
            if prop in graph[parent]:
                roots.update(find_roots(graph, prop, set([parent])))

    return roots

def find_roots(graph, prop, roots=None):
    if roots is None:
        roots = set()
    for node in graph.subjects(prop, None):
        if not node.has_property(prop):
            roots.add(node)
    for node in roots:
        children = graph.objects(node, prop)
        roots -= set(children)
    return roots

def find_roots(graph: rdflib.Graph, prop: rdflib.URIRef, roots: Optional[Set[rdflib.Node]] = None) -> Set[rdflib.Node]:
    if roots is None:
        roots = set()
    for child, parent in graph.subject_objects(prop):
        if child not in roots:
            roots.add(child)
            find_roots(graph, prop, roots)
    return roots

