def load_configurations(config_filenames, overrides=None, resolve_env=True):
    config_files = {}
    parse_errors = []
    for config_filename in config_filenames:
        try:
            with open(config_filename, "r") as f:
                config_file = f.read()
            if resolve_env:
                config_file = config_file.format(**os.environ)
            config = json.loads(config_file)
            config_files[config_filename] = config
        except (OSError, json.JSONDecodeError) as e:
            logger.error("Failed to load or parse configuration file: %s", config_filename, exc_info=e)
            parse_errors.append(logger.record)
