def protocol_handlers(cls, protocol_version=None):
    """Return a dictionary of available Bolt protocol handlers, keyed by version tuple. If an explicit protocol version is provided, the dictionary will contain either zero or one items, depending on whether that version is supported."""

    handlers = {}

    for ver, handler in cls.__dict__.items():
        if isinstance(handler, tuple) and len(handler) == 2:
            handlers[handler] = getattr(cls, handler[1])

    if protocol_version is not None:
        if not isinstance(protocol_version, tuple):
            raise TypeError("Protocol version must be passed in a tuple")
        if not (0, len(protocol_version) == 2):
            raise ValueError("Protocol version must be two numbers")
        if protocol_version in handlers:
            return {protocol_version: handlers[protocol_version]}
        return {}

    return handlers

