    :param spec_content: Content of spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    :raise IRValidatorException: When mandatory data is missing in spec file
    """
    if spec_content is None:
        raise ValueError("spec_content cannot be None")

    spec = yaml.safe_load(spec_content)

    if "name" not in spec:
        raise IRValidatorException("name is a mandatory field")
    if "columns" not in spec:
        raise IRValidatorException("columns is a mandatory field")
    if not isinstance(spec["columns"], list):
        raise IRValidatorException("columns must be a list")
    for col in spec["columns"]:
        if "name" not in col:
            raise IRValidatorException("name is a mandatory field in columns")

    return spec

